-- Eli Sparks voice, fourth coach, high-energy encouragement. Safe to re-run.
-- INSERT voice IGNORE. Lines upsert on (voice_id, bucket, sort_order).


UPDATE coach_voices
SET description = 'High-energy and open-hearted. He believes in you louder than you believe in yourself, and says so. Praise is frequent and earned in the moment, not saved up. The reward is still growth, lean, definition, power, stamina, and mobility. He just wants you to feel every bit of it landing.',
    blurb = 'Loud belief. He is in your corner. The reps are proof you already have it.'
WHERE id = 'eli';

ON DUPLICATE KEY UPDATE title = VALUES(title), body = VALUES(body), is_active = 1;
